// Parse the LLM's structured JSON output and validate it against the prompt schema.
const ALLOWED = ['High-Value Dispute', 'Standard Dispute', 'Billing Inquiry', 'Operational Issue', 'Documentation Request', 'General Inquiry'];
const raw = String($input.first().json.text || '').replace(/```(json)?/gi, '').trim();
let out;
try { out = JSON.parse(raw); } catch (e) { throw new Error('LLM returned non-JSON output - ' + raw.slice(0, 200)); }
if (!ALLOWED.includes(out.classification)) throw new Error('LLM returned unknown classification - ' + out.classification);
const ticket = $('Normalize Ticket').first().json;
return [{ json: { ...ticket, ...out, ticket_id: ticket.ticket_id } }];

// Deterministic brand-safety guardrail: runs before ANY vendor-facing email (auto or HITL-approved).
// Blocks draft replies that mention US dollar amounts or contract timelines, even if the LLM ignored the negative prompt.
const t = $input.first().json;
const draft = String(t.draft_response || '').trim();
if (!draft) throw new Error('Guardrail blocked ticket ' + t.ticket_id + ' - empty draft_response');
const RULES = [
  ['dollar amount', /\$\s*\d|\bUSD\b|\bdollars?\b|\b\d[\d,]*(\.\d+)?\s*(k|K)\b/],
  ['monetary figure', /\b\d[\d,]*\.\d{2}\b|\b\d{1,3}(,\d{3})+\b/],
  ['contract timeline', /\bnet[\s-]?\d+\b|\b\d+\s*(business\s+|calendar\s+)?(hours?|days?|weeks?|months?)\b|\bwithin\s+\d+/i],
  ['SLA / deadline term', /\bSLA\b|\bdeadline\b|\bdue date\b|\bturnaround\b|\bguarantee/i],
];
const hits = RULES.filter(([, re]) => re.test(draft)).map(([name]) => name);
if (hits.length) {
  // Fail loudly: the ticket is isolated in the DLQ and no vendor email is sent.
  throw new Error('Guardrail blocked ticket ' + t.ticket_id + ' - draft_response contains ' + hits.join(', '));
}
return [{ json: t }];

